    for r in range(h):
        for c in range(w):
            if g[r][c] != 0:
                continue
            if r < 2 or c < 2:
                g[r][c] = 1
            elif r == 2 or c == 2:
                g[r][c] = 4
            else:
                g[r][c] = residues[(r + c) % period]
    return g
